def lesson(n,part,page,task,proof,steps,scenes,probes,rule,hint,caption,prompt=None,title=None,refs=None):
    c=area(n,part,[page],task,proof,hint,steps,scenes,probes,refs=refs or [123,124],title=title)
    c['source']['chapter']='XIV'
    c['review']['reviewer']=f'Атанасян и др., «Геометрия. 7–9 классы», редакция 2023 г., гл. XIV, печатная с. {page} (с. {page+1} файла). Сверены вид исходного задания и все подпункты.'
    c['help'][1]['text']=rule
    if prompt:c['answer']['prompt']=prompt
    c['visualization']['caption']=c['visualization']['model']['description']=caption+' Отрезок UW имеет длину 1.'
    return c


def inverse_motion():
    def scene(title,a,b,delta):
        dx,dy=delta
        return schematic(title,{'A':a,'B':b,'A′':(a[0]+dx,a[1]+dy),'B′':(b[0]+dx,b[1]+dy)},[('A','B'),('A′','B′'),('A','A′'),('B','B′')])
    return lesson(1257,'а',320,'Известно, что фигуру P можно совместить с фигурой Q движением. Докажи равенство в обратном порядке. Как совместить Q с P?',
      'Обозначим исходное движение через f. У каждой точки Q есть единственный прообраз в P, так как Q — весь образ P. Пусть X′ и Y′ — любые две точки плоскости, X и Y — их прообразы. Исходное движение даёт X′Y′=XY, значит, обратное отображение сохраняет расстояния. Оно отображает всю плоскость на себя и переводит Q в P. Поэтому Q равна P.',
      [('Найди обратный путь','В первом примере A переходит в A′. Чтобы попасть обратно, поменяй начало и конец пути. То же сделай с B′.','Обоснуй обратимость для каждой точки, включая точки внутри фигуры.'),
       ('Верни одну координату','Во втором примере сдвиг прибавил к абсциссе 4. У образа A′ абсцисса 5. Обратное действие вычитает 4.','Ещё один сдвиг вправо не вернёт точку к прежнему положению.'),
       ('Проверь расстояние','В третьем примере отрезок длины 6 лежит в фигуре Q. Обратное движение возвращает концы, сохраняя расстояние. Так рассуждаем для любой пары точек.','Для общего вывода используй определение движения, а не только измерение рисунка.')],
      [scene('Прямой и обратный переход',(0,0),(2,2),(4,1)),scene('Вычти исходное приращение',(1,0),(3,3),(4,2)),scene('Верни отрезок другой длины',(0,0),(6,0),(1,3))],
      [('Какова абсцисса A, если x(A′)=5 и прямой сдвиг прибавил 4?','1','Вычти 4 из координаты образа.'),('Какой длины отрезок вернётся, если длина его образа 6?','6','В любой паре прообразов сохраняется расстояние между точками.')],
      'Две фигуры равны, если движение переводит одну из них в другую. Обратное к движению существует и также сохраняет расстояния.',
      'Начни с произвольной пары точек в конечной плоскости и назови их прообразы.',
      'Один штрих указывает положение в Q. Отрезки AA′ и BB′ связывают соответствующие точки.','Докажи, что обратное отображение существует, сохраняет расстояния и переводит Q в P.')


def transitive_motion():
    def scene(title,a,b):
        first=lambda q:(q[0]+5,q[1]+2)
        second=lambda q:(-q[0],q[1])
        return segment_family(title,[a,b],[first(a),first(b)],[second(first(a)),second(first(b))])
    return lesson(1257,'б',320,'Фигуру P можно совместить с Q, а Q — с R. Докажи, что P и R тоже равны.',
      'Возьмём движение f из P на Q и движение g из Q на R. Для любой точки P делаем сначала f, затем g. Все точки попадают в R. Для каждой точки R можно вернуться через прообраз в Q к прообразу в P, поэтому получена вся фигура R. Последовательность двух движений сохраняет расстояния между произвольными точками и сама является движением. Она и устанавливает равенство P и R.',
      [('Собери цепочку','Выбери точку A в P. После первого движения это A′ в Q, после второго — A″ в R. Проследи тот же путь для B.','Порядок важен: второе движение должно принимать точки Q.'),
       ('Сравни концы отрезка','Во втором рисунке AB имеет длину 5. В среднюю фигуру перенесён тот же отрезок, затем его отразили.','Длины промежуточного и конечного отрезков не нужно складывать.'),
       ('Охвати всю конечную фигуру','Для любой точки R найди сначала прообраз в Q, затем в P. В третьем примере исходная длина 3. Проверь результат двух движений.','Одного включения в R недостаточно: покажи, что ни одна точка R не пропущена.')],
      [scene('Три положения отрезка',(0,0),(2,2)),scene('Сохрани длину 5',(0,0),(3,4)),scene('Проверь длину 3 на другой паре',(1,1),(4,1))],
      [('Если AB=5, чему равно A″B″?','5','Оба движения сохраняют длину.'),('Если A′B′=3, чему равно AB?','3','Первый образ имеет ту же длину, что исходный отрезок.')],
      'Последовательное выполнение двух движений даёт движение. Точки первого образа должны стать входом второго движения.',
      'Назови два заданных движения и порядок, в котором они переводят исходную фигуру в конечную.',
      'Штрихи отмечают положения в Q и в R. На чертеже показан один отрезок каждой фигуры.','Назови составное движение, объясни сохранение расстояний и получение всей фигуры R.')


def translation(title,points,edges,delta,anchor=None,other=None):
    dx,dy=delta
    moved={n+'′':(x+dx,y+dy) for n,(x,y) in points.items()}
    if anchor is None:anchor=(min(x for x,y in points.values())-1,min(y for x,y in points.values())-2)
    mx,my=anchor
    shown={**points,**moved,'M':anchor,'N':(mx+dx,my+dy)}
    if other:
        shown['K']=(1,-4.5)
        shown['L']=(1+other[0],-4.5+other[1])
    left=min(x for x,y in shown.values());low=min(y for x,y in shown.values())-1.5
    shown.update(U=(left,low),W=(left+1,low))
    segments=[*edges,*[(a+'′',b+'′') for a,b in edges],('M','N'),('U','W')]
    arrow=[]
    active=[('M','N',delta)]
    if other:
        segments.append(('K','L'))
        active.append(('K','L',other))
    for _,end,(vx,vy) in active:
        magnitude=hypot(vx,vy)
        if magnitude==0:continue
        ux,uy=vx/magnitude,vy/magnitude
        nx,ny=shown[end]
        arrow.extend(((nx,ny),(nx-.4*ux-.19*k*uy,ny-.4*uy+.19*k*ux)) for k in (-1,1))
    return graph(title,shown,edges=segments,lines=arrow)


