    parser.add_argument('--check',action='store_true')
    lessons=[inverse_motion(),transitive_motion(),translation_rule(),rotation_rule(),segment(),triangle('а'),triangle('б')]
    raw=json.dumps({'bookId':BOOK,'lessons':lessons},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:
        assert OUT.read_text()==raw
    else:
        OUT.write_text(raw)
